N = {k: 0 for k in range(p)}

# Iterate over all pairs (a, b) in {0, 1, ..., 60}
for a in range(p):
    for b in range(p):
        # Calculate a^2 + b^2 mod 61
        k = (a*a + b*b) % p
        N[k] += 1

# Output the distribution N_k
print("Distribution N_k for k=0 to 60:")
for k in range(p):
    print(f"N_{k}: {N[k]}")

# Also calculate the sum to ensure correctness (should be p^2 = 3721)
total_count = sum(N.values())
print(f"\nTotal count check: {total_count}")

p = 61
M = {k: 0 for k in range(p)}
for c in range(p):
    c_cubed = pow(c, 3, p)
    for d in range(p):
        d_cubed = pow(d, 3, p)
        k = (c_cubed - d_cubed) % p
        M[k] += 1

print("Distribution M_k:")
